"""Workspace-local atom packs (generated by explore crystallization).

A workspace may own packs that must not leak into the repository or the global
process registry.  Layout::

    <workspace>/.panguverse/packs/<pack>/pack.json
    <workspace>/.panguverse/packs/<pack>/atoms/<name>.py

``pack.json`` is a small manifest; every atom points at a Python module that
exposes ``run(ctx=None, **inputs)``.  The loader imports those modules and
builds regular :class:`~panguverse.core.atom.Atom` objects, so replay and normal
workflow execution use the generated atom instead of the original script file.
"""

from __future__ import annotations

import hashlib
import importlib.util
import json
import sys
from collections.abc import Mapping
from pathlib import Path
from typing import Any

from .atom import Atom
from .pack import AtomPack
from .registry import AtomRegistry

PACKS_REL = Path(".panguverse") / "packs"
MANIFEST_NAME = "pack.json"


def packs_root(workspace: str | Path) -> Path:
    return Path(workspace) / PACKS_REL


def _module_name(pack: str, atom: str, path: Path) -> str:
    # Content-addressed name: re-crystallizing an atom with new code must not
    # reuse a stale module from sys.modules in the long-running server.
    digest = hashlib.sha256(path.read_bytes()).hexdigest()[:12]
    safe = "".join(ch if ch.isalnum() or ch == "_" else "_" for ch in f"{pack}_{atom}")
    return f"panguverse_ws_{safe}_{digest}"


def _load_module(path: Path, *, pack: str, atom: str) -> Any:
    module_name = _module_name(pack, atom, path)
    existing = sys.modules.get(module_name)
    if existing is not None:
        return existing
    spec = importlib.util.spec_from_file_location(module_name, path)
    if spec is None or spec.loader is None:
        raise ImportError(f"无法加载原子模块: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[module_name] = module
    try:
        spec.loader.exec_module(module)
    except BaseException:
        sys.modules.pop(module_name, None)
        raise
    return module


def _atom_from_manifest(raw: Mapping[str, Any], *, base: Path, pack: str, domain: str) -> Atom:
    name = str(raw.get("name") or "").strip()
    if not name:
        raise ValueError("manifest 原子缺少 name")
    entry = str(raw.get("entry") or f"atoms/{name}.py")
    target = (base / entry).resolve()
    try:
        target.relative_to(base.resolve())
    except ValueError as exc:
        raise ValueError(f"原子入口越出包目录: {entry}") from exc
    if not target.is_file():
        raise FileNotFoundError(f"原子代码不存在: {target}")
    module = _load_module(target, pack=pack, atom=name)
    fn = getattr(module, "run", None)
    if not callable(fn):
        raise ValueError(f"原子模块缺少 run(): {target}")
    inputs = raw.get("inputs")
    outputs = raw.get("outputs")
    declared = raw.get("produces")
    if isinstance(declared, Mapping):
        produces = tuple(str(key) for key in declared)
    elif isinstance(declared, (list, tuple)):
        produces = tuple(str(item) for item in declared)
    else:
        # 旧包没有 produces：output_paths 的键就是任务产出物（向后兼容）。
        paths = raw.get("output_paths")
        produces = tuple(str(key) for key in paths) if isinstance(paths, Mapping) else ()
    return Atom(
        name=name,
        fn=fn,
        description=str(raw.get("description") or ""),
        inputs=dict(inputs) if isinstance(inputs, Mapping) else {},
        outputs=dict(outputs) if isinstance(outputs, Mapping) else {},
        tags=tuple(raw.get("tags") or ("explore", "new_atom")),
        category=str(raw.get("category") or "script"),
        domain=str(raw.get("domain") or domain),
        pack=pack,
        effects=tuple(raw.get("effects") or ("write",)),
        capabilities=tuple(raw.get("capabilities") or ()),
        idempotent=bool(raw.get("idempotent", True)),
        failure_class=str(raw.get("failure_class") or ""),
        source="explore",
        version=str(raw.get("version") or "0.1.0"),
        produces=produces,
        sites=tuple(str(site) for site in (raw.get("sites") or ()) if str(site).strip()),
    )


def load_workspace_packs(workspace: str | Path) -> list[AtomPack]:
    """Load every valid workspace pack; malformed packs are skipped, not fatal."""
    root = packs_root(workspace)
    if not root.is_dir():
        return []
    packs: list[AtomPack] = []
    for directory in sorted(child for child in root.iterdir() if child.is_dir()):
        manifest_path = directory / MANIFEST_NAME
        if not manifest_path.is_file():
            continue
        try:
            data = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not isinstance(data, Mapping):
            continue
        header = data.get("pack") if isinstance(data.get("pack"), Mapping) else data
        name = str(header.get("name") or directory.name).strip()
        if not name:
            continue
        domain = str(header.get("domain") or "explore")
        pack = AtomPack(
            name=name,
            domain=domain,
            version=str(header.get("version") or "0.1.0"),
            description=str(header.get("description") or ""),
            requires=tuple(header.get("requires") or ()),
            tags=tuple(header.get("tags") or ("explore",)),
            source="explore",
            path=str(directory),
        )
        for raw in data.get("atoms") or []:
            if not isinstance(raw, Mapping):
                continue
            try:
                pack.atoms.append(_atom_from_manifest(raw, base=directory, pack=name, domain=domain))
            except Exception:  # noqa: BLE001 - 单个坏原子不应拖垮整个工作台
                continue
        if pack.atoms:
            packs.append(pack)
    return packs


def workspace_registry(workspace: str | Path, base: Any = None) -> Any:
    """Return a registry view containing the workspace's generated atoms.

    A plain injected test registry (without ``extend``/``packs``) is returned
    unchanged; production registries are cloned so the process-global registry
    is never polluted by a workspace pack.
    """
    if base is None:
        from .registry import default_registry

        base = default_registry()
    if not hasattr(base, "extend") or not hasattr(base, "register_pack"):
        return base
    packs = load_workspace_packs(workspace)
    if not packs:
        return base
    registry = AtomRegistry(f"workspace:{Path(workspace)}")
    registry.extend(base)
    for pack in packs:
        registry.register_pack(pack, replace=True)
    return registry


def list_workspace_pack_manifests(workspace: str | Path) -> list[dict[str, Any]]:
    root = packs_root(workspace)
    out: list[dict[str, Any]] = []
    if not root.is_dir():
        return out
    for directory in sorted(child for child in root.iterdir() if child.is_dir()):
        manifest = directory / MANIFEST_NAME
        if not manifest.is_file():
            continue
        try:
            data = json.loads(manifest.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if isinstance(data, Mapping):
            out.append({"path": str(manifest), **dict(data)})
    return out


__all__ = [
    "MANIFEST_NAME",
    "PACKS_REL",
    "list_workspace_pack_manifests",
    "load_workspace_packs",
    "packs_root",
    "workspace_registry",
]
